<script setup lang="ts">
import { reactive, ref } from 'vue'
import { Plus, Trash2, FolderKanban } from 'lucide-vue-next'
import { state, addProject, removeItem } from '../lib/store'
import { brl, dateBR, projectLabels, todayLocal } from '../lib/format'
import type { ProjectStatus } from '../lib/types'
const statuses: ProjectStatus[] = ['planejado','andamento','revisao','entregue']
const showForm = ref(false)
const form = reactive({ name: '', client: '', status: 'planejado' as ProjectStatus, deadline: todayLocal(), value: 0 })
function submit() { if (!form.name.trim() || !form.client.trim() || form.value < 0) return; addProject({ ...form, name: form.name.trim(), client: form.client.trim(), value: Number(form.value) }); Object.assign(form, { name: '', client: '', status: 'planejado', deadline: todayLocal(), value: 0 }); showForm.value = false }
function drop(id: string) { if (confirm('Excluir este projeto?')) removeItem('projects', id) }
</script>
<template><div class="view-enter"><div class="page-intro"><div><p class="eyebrow"><span class="eyebrow-line"></span> PRODUÇÃO</p><h1>Projetos</h1><p class="page-subtitle">Gerencie entregas, clientes, prazos e andamento.</p></div><button class="btn btn-dark" @click="showForm = true"><Plus :size="17"/> Novo projeto</button></div>
  <div class="surface"><div class="list-toolbar"><h2>Todos os projetos</h2><span class="item-counter">{{ state.projects.length }} projeto(s)</span></div><div class="table-wrap"><table v-if="state.projects.length" class="data-table"><thead><tr><th>PROJETO</th><th>CLIENTE</th><th>PRAZO</th><th>VALOR COMBINADO</th><th>STATUS</th><th>AÇÕES</th></tr></thead><tbody><tr v-for="project in state.projects" :key="project.id"><td class="strong">{{ project.name }}</td><td>{{ project.client }}</td><td>{{ dateBR(project.deadline) }}</td><td>{{ brl(project.value) }}</td><td><select v-model="project.status" class="status-select" :class="project.status" :aria-label="`Status de ${project.name}`"><option v-for="s in statuses" :key="s" :value="s">{{ projectLabels[s] }}</option></select></td><td><button class="icon-button danger" :aria-label="`Excluir ${project.name}`" @click="drop(project.id)"><Trash2 :size="16" /></button></td></tr></tbody></table><div v-else class="empty"><FolderKanban :size="27"/><b>Sem projetos cadastrados</b><p>Comece pelos seus projetos de portfólio ou pelos trabalhos já contratados.</p><button class="btn btn-outline" @click="showForm = true">Adicionar projeto</button></div></div></div>
  <div v-if="showForm" class="modal-backdrop" @click.self="showForm = false"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="project-title"><div class="modal-head"><h2 id="project-title">Novo projeto</h2><button class="icon-button" aria-label="Fechar" @click="showForm = false">✕</button></div><form @submit.prevent="submit"><div class="field"><label for="p-name">Nome do projeto *</label><input id="p-name" v-model="form.name" required maxlength="120" autofocus placeholder="Ex.: Site casamento Marina & Lucas"/></div><div class="field"><label for="p-client">Cliente *</label><input id="p-client" v-model="form.client" required maxlength="120" placeholder="Nome do cliente ou Portfólio"/></div><div class="form-row"><div class="field"><label for="p-deadline">Prazo previsto</label><input id="p-deadline" v-model="form.deadline" type="date" /></div><div class="field"><label for="p-value">Valor combinado (R$)</label><input id="p-value" v-model.number="form.value" type="number" min="0" step="0.01" required /></div></div><div class="field"><label for="p-status">Status inicial</label><select id="p-status" v-model="form.status"><option v-for="s in statuses" :key="s" :value="s">{{ projectLabels[s] }}</option></select></div><div class="modal-actions"><button type="button" class="btn btn-outline" @click="showForm = false">Cancelar</button><button class="btn btn-dark" type="submit">Salvar projeto</button></div></form></div></div>
</div></template>
